#include <iostream>
#include <map>
#include <ranges>

int main() {
    using namespace std;
    unsigned N, K;
    cin >> N >> K;

    unsigned ans{};

    // S の値からいつ出現したかを求める連想配列
    map<unsigned, unsigned> prev;
    prev[0] = 0;
    for (unsigned S{}, last{}; const auto &[i, A] : views::istream<unsigned>(cin) | views::enumerate) {
        (S += A) %= K; // 累積和を求めて
        // 累積和の値がすでに出現していて、かつ選んだ区間と重なっていなければ
        if (prev.contains(S) && last <= prev[S]) {
            ++ans;
            last = i + 1; // 区間を選ぶ
        }
        prev[S] = i + 1; // 番号を更新
    }

    cout << ans << endl;
    return 0;
}
